using System;using System.IO;using System.Collections.Generic;using System.Web.Script.Serialization;using Recovered.Gameplay;public class WorldPhase7720261013Verify {public static int Main(string[] args){var json=new JavaScriptSerializer();json.MaxJsonLength=256*1024*1024;var data=World19Support.Obj(json.DeserializeObject(World19Support.Input(args[0])));var regions=World19Support.Arr(data["regions"]);int cases=0,checks=0,failures=0;var errors=new List<object>();foreach(object v in World19Support.Arr(data["cases"])){var row=World19Support.Obj(v);var expected=World19Support.Obj(row["expected"]);var bad=new List<string>();try{var m=World19Support.Setup(regions,row);var trace=new List<object>();PtlSubmitLink.Link(m,World19Support.U(row["packet"]),delegate(SoundSetupImage image,uint owner,uint workspace){trace.Add(new object[]{0x607590u,new uint[]{owner,workspace}});if(row.ContainsKey("mutations"))foreach(object item in World19Support.Arr(row["mutations"])){var patch=World19Support.Obj(item);uint at=World19Support.U(patch["address"]);byte[] bytes=Convert.FromBase64String((string)patch["data"]);for(int i=0;i<bytes.Length;i++)image.Byte(at+(uint)i,bytes[i]);}});checks+=2;if(!World19Support.Equal(trace,expected["trace"]))bad.Add("ordered owner preparation boundary");if(World19Support.Hash(m,regions)!=(string)expected["sha256"])bad.Add("complete command linkage image");}catch(Exception ex){bad.Add(ex.ToString());}if(bad.Count!=0){failures++;if(errors.Count<12)errors.Add(new{cases,bad});}cases++;}string report=json.Serialize(new{cases,checks,mismatches=failures,errors,binarySha256=data["binarySha256"]});File.WriteAllText(args[1],report);Console.WriteLine(report);return failures==0?0:1;}}
